def num(v):
  if isinstance(v,(int,float)): return float(v)
  try: return float(str(v).strip())
  except: return 0.0

import shutil, openpyxl, datetime
shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = vals['Daily Numbers']
err = vals['Errors']

def clean(v):
    if v is None: return None
    if isinstance(v, str): return v.strip()
    return v

def norm_wh(v):
    if v is None: return None
    if isinstance(v, str):
       s=v.strip()
       try:
          f=float(s)
          return int(f) if f.is_integer() else f
       except: return s
    if isinstance(v, float) and v.is_integer(): return int(v)
    return v

def norm_date(v):
    if isinstance(v, datetime.datetime): return v.date()
    if isinstance(v, datetime.date): return v
    if isinstance(v, str):
       s=v.strip()
       for fmt in ('%Y-%m-%d %H:%M:%S','%Y-%m-%d','%d/%m/%Y','%m/%d/%Y'):
          try: return datetime.datetime.strptime(s, fmt).date()
          except: pass
    return v

def norm_code(v):
    if v is None: return None
    return str(v).strip().upper()

def norm_user(v):
    if v is None: return None
    return str(v).strip()

# Preprocess errors into list of tuples? 
err_rows=[]
for r in range(2, err.max_row+1):
    wh = norm_wh(err.cell(r,9).value) # I
    dt = norm_date(err.cell(r,17).value) # Q
    code = norm_code(err.cell(r,2).value) # B
    user = norm_user(err.cell(r,28).value) # AB
    qty = err.cell(r,13).value # M
    if qty is None: qty=0
    try: qty=float(qty)
    except: qty=0
    err_rows.append((wh,dt,code,user,qty))

# For each Daily row 3..24
for r in range(3,25):
    wh = norm_wh(ws.cell(r,1).value)
    dt = norm_date(ws.cell(r,12).value)
    code = norm_code(ws.cell(r,5).value) # E
    users = set()
    for c in range(7,11): # G-J
       u=norm_user(ws.cell(r,c).value)
       if u: users.add(u)
    total=0.0
    for e_wh,e_dt,e_code,e_user,e_qty in err_rows:
       if e_wh == wh and e_dt == dt and e_code == code and e_user in users:
           if code == 'IR' and e_qty <= 0: continue
           total += e_qty
    # write int if integer
    if total == int(total): total=int(total)
    wb['Daily Numbers'].cell(r,17).value = total # Q
